  "connector_id": "AOP0OZUB3JwAtE25PST0",
  "interface": {
    "input": "{
    "type": "object",
    "properties": {
        "parameters": {
            "type": "object",
            "properties": {
                "texts": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "embedding_types": {
                    "type": "array",
                    "items": {
                        "type": "string",
                        "enum": ["float", "int8", "uint8", "binary", "ubinary"]
                    }
                },
                "truncate": {
                    "type": "array",
                    "items": {
                        "type": "string",
                        "enum": ["NONE", "START", "END"]
                    }
                },
                "input_type": {
                    "type": "string",
                    "enum": ["search_document", "search_query", "classification", "clustering"]
                }
            },
            "required": ["texts"]
        }
    },
    "required": ["parameters"]
}",
    "output": "{
    "type": "object",
    "properties": {
        "inference_results": {
            "type": "array",
