                                            "type": "string",
                                            "format": "uuid"
                                        },
                                        "texts": {
                                            "type": "array",
                                            "items": {
                                                "type": "string"
                                            }
                                        },
                                        "embeddings": {
                                            "type": "object",
                                            "properties": {
                                                "binary": {
                                                    "type": "array",
